ST.xhtml:p:
nPerfectKRType :=  g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.dPerfectKRType;
dPerfectEndCutDis := g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.dPerfectEndCutDis;
nCutting_Frequency := g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.nCutting_Frequency;
nCutting_Duty := UINT_TO_LREAL(g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.nCutting_Duty);
nPrefectEndCutFrequency := DINT_TO_UINT(g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.nPrefectEndCutFrequency);
dPrefectEndCutDuty  :=  g_TechData.multilTechData[g_nToolNum-1].DIRECUT_CUTTING.dPrefectEndCutDuty;
  CASE nPerfectKRType OF
    1:(*方式1：直接把PWM拉成0*)
      g_nPwmFreq := 0;
      g_nPwmDuty :=0;

    2:(*方式2：PWM缓降到另一个PWM*)
       dEndCutDis:=dPerfectEndCutDis;
      IF dEndCutDis <0.0 THEN(**防止除零***)
        dEndCutDis:=0.1;
      END_IF;
      dCurrentPwmFreq:= UINT_TO_UDINT(nCutting_Frequency);
      dCurrentPwmDuty:=  LREAL_TO_UDINT(nCutting_Duty);
      dFinallyPwmFreq:= UINT_TO_UDINT(nPrefectEndCutFrequency);
      dFinallyPwmDuty:= LREAL_TO_UDINT(dPrefectEndCutDuty);

      g_dGoneDist := g_dGoneDist + g_fiXYCurrentSpeedBuff*0.001;(**速度乘以周期就是移动的距离**)  
      dSlope := UDINT_TO_LREAL(dFinallyPwmFreq) -  UDINT_TO_LREAL(dCurrentPwmFreq);     
      dSlope := dSlope / dEndCutDis;
      IF g_dGoneDist < dEndCutDis THEN(*只有不为0的时候才输出*)  
          IF dSlope > 0.0 THEN       
            g_nPwmFreq   := LREAL_TO_UINT(UDINT_TO_LREAL(dCurrentPwmFreq)) + LREAL_TO_UINT((ABS(dSlope)*g_dGoneDist));
          ELSE 
            g_nPwmFreq   := LREAL_TO_UINT(UDINT_TO_LREAL(dCurrentPwmFreq)) - LREAL_TO_UINT((ABS(dSlope)*g_dGoneDist));
          END_IF;
      END_IF;

      dSlope := UDINT_TO_LREAL(dFinallyPwmDuty)-UDINT_TO_LREAL(dCurrentPwmDuty);
      dSlope := dSlope / dEndCutDis; 
      IF g_dGoneDist < dEndCutDis THEN (*只有不为0的时候才输出*)  
          IF dSlope > 0.0 THEN 
            g_nPwmDuty   := LREAL_TO_UINT(nCutting_Duty + (ABS(dSlope)*g_dGoneDist));  
          ELSE 
            g_nPwmDuty   := LREAL_TO_UINT(nCutting_Duty - (ABS(dSlope)*g_dGoneDist)); 
          END_IF;
      END_IF;
      IF g_nPwmFreq > 20000 THEN
        g_nPwmFreq :=20000;
      END_IF;
      IF g_nPwmDuty > 100 THEN
        g_nPwmDuty :=100;
      END_IF;

      IF g_nPwmFreq < 0 THEN
        g_nPwmFreq :=0;
      END_IF;
      IF g_nPwmDuty < 0 THEN
        g_nPwmDuty :=0;
      END_IF;    

    3:(*方式3：PWM突变到另一个PWM*) 
      g_nPwmFreq   :=nPrefectEndCutFrequency;
      g_nPwmDuty   :=LREAL_TO_UINT(dPrefectEndCutDuty); 
  END_CASE;
